@Service
public class PaymentGatewayClient {
    private final CircuitBreaker circuitBreaker;

    public PaymentGatewayClient(CircuitBreakerRegistry registry) {
        CircuitBreakerConfig config = CircuitBreakerConfig.custom()
            .failureRateThreshold(50.0f)
            .slowCallRateThreshold(30.0f)
            .slowCallDurationThreshold(Duration.ofSeconds(2))
            .slidingWindowType(SlidingWindowType.COUNT_BASED)
            .slidingWindowSize(100)
            .minimumNumberOfCalls(20)
            .waitDurationInOpenState(Duration.ofSeconds(15))
            .permittedNumberOfCallsInHalfOpenState(5)
            .build();
        this.circuitBreaker = registry.circuitBreaker("paymentService", config);
    }

    public PaymentResult processPayment(PaymentRequest request) {
        Supplier<PaymentResult> decorated = CircuitBreaker
            .decorateSupplier(circuitBreaker, () -> callStripeAPI(request));
        return Try.ofSupplier(decorated)
            .recover(CallNotPermittedException.class, ex -> fallbackOfflineQueue(request))
            .recover(Exception.class, ex -> fallbackOfflineQueue(request))
            .get();
    }
}
